window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-36601\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σινιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 451 na letra σ · nº geral 36601</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 joeirar; peneirar 2 pôr à prova; testar. 〈σινίον〉</p></section></article>\n<article id=\"entry-dgp-36602\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σινίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 452 na letra σ · nº geral 36602</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. peneira.</p></section></article>\n<article id=\"entry-dgp-36603\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίνις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 453 na letra σ · nº geral 36603</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. ιν (ὁ) aquele que causa dano, que prejudica; malfeitor. 〈σίνω〉</p></section></article>\n<article id=\"entry-dgp-36604\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 454 na letra σ · nº geral 36604</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. σίνω.</p></section></article>\n<article id=\"entry-dgp-36605\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίνος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 455 na letra σ · nº geral 36605</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dano; prejuízo; ruína 2 Medic. lesão 3 desgraça; infortúnio; flagelo. 〈σίνω〉</p></section></article>\n<article id=\"entry-dgp-36606\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίντης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 456 na letra σ · nº geral 36606</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 saqueador; ladrão; gatuno 2 serpente; víbora ♦ adj. masc. e fem. 3 devastador; predador. 〈σίνω〉</p></section></article>\n<article id=\"entry-dgp-36607\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 457 na letra σ · nº geral 36607</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 prejudicar; causar dano ♦ méd. σίνομαι (impf. ἐσινόμην, fut. σινήσομαι, aor. ἐσινάμην, perf. σέσιμμαι) 2 causar dano; fazer mal a; prejudicar, ac.: σ. πολεμίους fazer muito mal aos inimigos, σ. γῆν ou χώραν her. devastar um território 3 depredar; roubar; devastar 4 ferir 5 fazer perecer 6 prejudicar alguém, ac.</p></section></article>\n<article id=\"entry-dgp-36608\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σινωπεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 458 na letra σ · nº geral 36608</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitante de Sinope; sinopense. 〈Σινώπη〉</p></section></article>\n<article id=\"entry-dgp-36609\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σινώπη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 459 na letra σ · nº geral 36609</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Sinope, n. de c. da Paflagônia 2 Sinope, n. de m.</p></section></article>\n<article id=\"entry-dgp-36610\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σινωπικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 460 na letra σ · nº geral 36610</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Sinope. 〈Σινώπη〉</p></section></article>\n<article id=\"entry-dgp-36611\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίπυδνος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 461 na letra σ · nº geral 36611</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σιπύη.</p></section></article>\n<article id=\"entry-dgp-36612\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιπύη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 462 na letra σ · nº geral 36612</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arca para pão e farinha.</p></section></article>\n<article id=\"entry-dgp-36613\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίραιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 463 na letra σ · nº geral 36613</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vinho novo encorpado.</p></section></article>\n<article id=\"entry-dgp-36614\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιρός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 464 na letra σ · nº geral 36614</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cavidade no chão ou recipiente enterrado para conservar cereais; silo.</p></section></article>\n<article id=\"entry-dgp-36615\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίστρος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 465 na letra σ · nº geral 36615</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de planta.</p></section></article>\n<article id=\"entry-dgp-36616\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σισύρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 466 na letra σ · nº geral 36616</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">manto de pele de cabra, usada de dia como veste e à noite como coberta.</p></section></article>\n<article id=\"entry-dgp-36617\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίσυρνα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 467 na letra σ · nº geral 36617</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σισύρα.</p></section></article>\n<article id=\"entry-dgp-36618\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σισυρνοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 468 na letra σ · nº geral 36618</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">envolto em pele de cabra. 〈σίσυρνα, φέρω〉</p></section></article>\n<article id=\"entry-dgp-36619\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σισύφειος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 469 na letra σ · nº geral 36619</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Sísifo. 〈Σίσυφος〉</p></section></article>\n<article id=\"entry-dgp-36620\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σισυφίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 470 na letra σ · nº geral 36620</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho ou descendente de Sísifo. 〈Σίσυφος〉</p></section></article>\n<article id=\"entry-dgp-36621\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σίσυφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 471 na letra σ · nº geral 36621</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Sísifo, rei de Corinto, renomado por sua velhacaria.</p></section></article>\n<article id=\"entry-dgp-36622\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σῖτα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 472 na letra σ · nº geral 36622</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. σῖτος.</p></section></article>\n<article id=\"entry-dgp-36623\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιταγωγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 473 na letra σ · nº geral 36623</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conduzir um carro de trigo ♦ méd. 2 importar trigo. 〈σιταγωγός〉</p></section></article>\n<article id=\"entry-dgp-36624\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιταγωγία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 474 na letra σ · nº geral 36624</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">transporte de trigo. 〈σιταγωγός〉</p></section></article>\n<article id=\"entry-dgp-36625\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιταγωγός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 475 na letra σ · nº geral 36625</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que transporta trigo. 〈σῖτος, ἄγω〉</p></section></article>\n<article id=\"entry-dgp-36626\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτάριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 476 na letra σ · nº geral 36626</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequena porção de alimento 2 pedaço de pão. 〈σῖτος〉</p></section></article>\n<article id=\"entry-dgp-36627\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτέσκοντο</h1><div class=\"entry-meta\"><span>DGP · ordem 477 na letra σ · nº geral 36627</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª impf. iter. méd. de σιτέω.</p></section></article>\n<article id=\"entry-dgp-36628\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτεύεσκον</h1><div class=\"entry-meta\"><span>DGP · ordem 478 na letra σ · nº geral 36628</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. iter. de σιτεύω.</p></section></article>\n<article id=\"entry-dgp-36629\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτευτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 479 na letra σ · nº geral 36629</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que alimenta (o gado). 〈σιτεύω〉</p></section></article>\n<article id=\"entry-dgp-36630\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτευτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 480 na letra σ · nº geral 36630</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cevado; bem alimentado; bem nutrido. 〈σιτεύω〉</p></section></article>\n<article id=\"entry-dgp-36631\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 481 na letra σ · nº geral 36631</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 alimentar; nutrir; engordar (animais) 2 fornecer grãos (para o altar) ♦ méd. (só pres.) 3 alimentar-se de, ac. 〈σῖτος〉</p></section></article>\n<article id=\"entry-dgp-36632\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 482 na letra σ · nº geral 36632</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 alimentar ♦ ger. méd. (impf. ἐσιτούμην, fut. σιτήσομαι, aor. ἐσιτήθην) 2 alimentar-se de algo, ac., dat. e ἀπό e gen. 〈σῖτος〉</p></section></article>\n<article id=\"entry-dgp-36633\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτηρέσιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 483 na letra σ · nº geral 36633</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Mil. fornecimento de víveres ou de dinheiro; soldo 2 em Roma, distribuição de grãos para os pobres. 〈σιτηρός〉</p></section></article>\n<article id=\"entry-dgp-36634\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτηρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 484 na letra σ · nº geral 36634</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de trigo 2 feito de trigo 3 comestível ♦ τὰ σιτηρά 4 cereais. 〈σῖτος〉</p></section></article>\n<article id=\"entry-dgp-36635\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίτησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 485 na letra σ · nº geral 36635</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de alimentar-se; alimentação; alimento 2 sustento custeado pelo Estado no Pritaneu 3 alimento; comida. 〈σιτέω〉</p></section></article>\n<article id=\"entry-dgp-36636\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτιεῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 486 na letra σ · nº geral 36636</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. méd. jôn. de σιτίζω.</p></section></article>\n<article id=\"entry-dgp-36637\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 487 na letra σ · nº geral 36637</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. desus., aor. ἐσίτισα, perf. desus.) 1 alimentar; nutrir alguém, ac., de algo, ac. ♦ méd. (só pres. e perf. σεσίτισμαι) 2 alimentar-se de, ac. 〈σῖτος〉</p></section></article>\n<article id=\"entry-dgp-36638\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 488 na letra σ · nº geral 36638</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do trigo; de cereal: σ. νόμος plut. lei sobre os cereais, σιτικοὶ καρποί D.S. os cereais. 〈σῖτος〉</p></section></article>\n<article id=\"entry-dgp-36639\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 489 na letra σ · nº geral 36639</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. pl. 1 grão; cereal 2 pão 3 alimento; víveres; provisão; refeição 4 pensão alimentar custeada pelo Estado no Pritaneu. 〈σῖτος〉</p></section></article>\n<article id=\"entry-dgp-36640\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτιστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 490 na letra σ · nº geral 36640</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 bem nutrido; cevado; gordo (animal) ♦ τὰ σιτιστά 2 animais gordos. 〈σιτίζω〉</p></section></article>\n<article id=\"entry-dgp-36641\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτοβόλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 491 na letra σ · nº geral 36641</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">celeiro para grãos. 〈σῖτος, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-36642\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτοδείας, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 492 na letra σ · nº geral 36642</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. σιτοδηΐη, ης (ἡ) carência de trigo ou de víveres; carestia; escassez. 〈σῖτος, δέω2〉</p></section></article>\n<article id=\"entry-dgp-36643\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτοδοτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 493 na letra σ · nº geral 36643</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prover alguém, ac., de grãos, de víveres ♦ pas. 2 receber víveres 3 receber uma cota de trigo, em Roma. 〈σῖτος, δίδωμι〉</p></section></article>\n<article id=\"entry-dgp-36644\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτολογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 494 na letra σ · nº geral 36644</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colheita de cereais. 〈σῖτος, λέγω〉</p></section></article>\n<article id=\"entry-dgp-36645\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτομετρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 495 na letra σ · nº geral 36645</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exercer o cargo de σιτομέτρης 2 distribuir trigo ou víveres a alguém, dat. 3 prover alguém, ac., de víveres ♦ pas. 4 receber víveres. 〈σιτόμετρον〉</p></section></article>\n<article id=\"entry-dgp-36646\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτομέτρης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 496 na letra σ · nº geral 36646</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inspetor de medidas de grãos 2 distribuidor de porções de grãos. 〈σῖτος, μέτρον〉</p></section></article>\n<article id=\"entry-dgp-36647\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτομετρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 497 na letra σ · nº geral 36647</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">distribuição de porções de trigo ou de víveres. 〈σιτομέτρης〉</p></section></article>\n<article id=\"entry-dgp-36648\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτομέτριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 498 na letra σ · nº geral 36648</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. ração de grãos ou de víveres. 〈σιτομέτρης〉</p></section></article>\n<article id=\"entry-dgp-36649\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτόμετρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 499 na letra σ · nº geral 36649</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σιτομετρία.</p></section></article>\n<article id=\"entry-dgp-36650\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σῖτον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 500 na letra σ · nº geral 36650</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. pl. σῖτα = σῖτος.</p></section></article>\n<article id=\"entry-dgp-36651\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτονόμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 501 na letra σ · nº geral 36651</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que fornece, que distribui trigo ou víveres 2 que alimenta; que faz viver. 〈σῖτος, νέμω〉</p></section></article>\n<article id=\"entry-dgp-36652\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτοποιέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 502 na letra σ · nº geral 36652</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer pão 2 preparar alimento para alguém, dat. ♦ méd. 3 preparar alimento para si 4 alimentar-se; comer. 〈σιτοποιός〉</p></section></article>\n<article id=\"entry-dgp-36653\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτοποιΐα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 503 na letra σ · nº geral 36653</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">preparação de alimentos. 〈σιτοποιός〉</p></section></article>\n<article id=\"entry-dgp-36654\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτοποιϊκός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 504 na letra σ · nº geral 36654</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">concernente à preparação do pão ou dos alimentos. 〈σιτοποιός〉</p></section></article>\n<article id=\"entry-dgp-36655\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτοποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 505 na letra σ · nº geral 36655</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que faz pão 2 da fabricação do pão: σ. ἀνάγκη eur. necessidade de fazer pão ♦ ὁ σιτοποιός 3 padeiro. 〈σῖτος, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-36656\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτοπομπία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 506 na letra σ · nº geral 36656</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">transporte de trigo ou de víveres. 〈σῖτος, πέμπω〉</p></section></article>\n<article id=\"entry-dgp-36657\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σῖτος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 507 na letra σ · nº geral 36657</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cereal (trigo ou cevada) em grãos: σῖτον ποιεῖν dem. cultivar o trigo 2 trigo moído; farinha: σῖτος μεμαγμένος tuc. massa de farinha de trigo, i.e., pão, σῖτος ὀπτός her. farinha assada, i.e., pão 3 pão: σῖτον ποιεῖν xen. fazer pão, σῖτον ἔδειν, σ. ἐσθίειν hom. comer pão 4 alimento sólido; alimento: σῖτον αἱρεῖσθαι her. tomar alimento 5 víveres; provisão (para o exército) 6 forragem (para animais) 7 Jur., em Atenas, pensão alimentar (para viúvas, órfãos): δίκη σίτου IS. processo de demanda de pensão alimentar, σῖτον διδόναι dem. conceder uma pensão alimentar 8 em Roma, distribuição de trigo ao povo 9 matéria fecal; excrementos.</p></section></article>\n<article id=\"entry-dgp-36658\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτοφάγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 508 na letra σ · nº geral 36658</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se alimenta de cereal; que come pão. 〈σῖτος, φαγεῖν〉</p></section></article>\n<article id=\"entry-dgp-36659\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 509 na letra σ · nº geral 36659</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que transporta cereal ou víveres 2 que produz cereal. 〈σῖτος, φέρω〉</p></section></article>\n<article id=\"entry-dgp-36660\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σιτώ, οῦς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 510 na letra σ · nº geral 36660</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Sito, epít. de Deméter. 〈σῖτος〉</p></section></article>\n<article id=\"entry-dgp-36661\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 511 na letra σ · nº geral 36661</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">campo de trigo; trigal. 〈σῖτος〉</p></section></article>\n<article id=\"entry-dgp-36662\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιτώνης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 512 na letra σ · nº geral 36662</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 em Atenas, comissário encarregado da compra do trigo 2 comerciante de trigo. 〈σῖτος, ὠνέομαι〉</p></section></article>\n<article id=\"entry-dgp-36663\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιφλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 513 na letra σ · nº geral 36663</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estropiar; mutilar.</p></section></article>\n<article id=\"entry-dgp-36664\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σίφνος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 514 na letra σ · nº geral 36664</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Sifnos, ilha das Cícladas.</p></section></article>\n<article id=\"entry-dgp-36665\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σίφων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 515 na letra σ · nº geral 36665</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tubo oco; cano 2 sifão 3 canal 4 cano de drenagem 5 bomba de água 6 trompa de inseto 7 membro viril 8 bomba para apagar incêndio.</p></section></article>\n<article id=\"entry-dgp-36666\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σιών</h1><div class=\"entry-meta\"><span>DGP · ordem 516 na letra σ · nº geral 36666</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. (ἡ) Sião, monte onde Jerusalém está situada.</p></section></article>\n<article id=\"entry-dgp-36667\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιωπάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 517 na letra σ · nº geral 36667</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐσιώπων, fut. σιωπήσομαι e σιωπήσω, aor. ἐσιώπησα, perf. σεσιώπηκα; pas. fut. σιωπηθήσομαι, aor. ἐσιωπήθην, perf. σεσιώπημαι) 1 intr. manter-se em silêncio junto a alguém, dat. ou πρός ac., sobre algo, ὑπέρ ou περί e gen. 2 guardar silêncio sobre; manter em segredo; ocultar algo, ac. ♦ méd. 3 fazer calar ♦ pas. 4 ser mantido em segredo. 〈σιωπή〉</p></section></article>\n<article id=\"entry-dgp-36668\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιωπή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 518 na letra σ · nº geral 36668</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 silêncio: σιωπὴν ποιεῖν ISÓCR., ποιεῖσθαι xen. mandar fazer silêncio 2 hábito do silêncio 3 vida obscura, sem notoriedade ♦ σιωπῇ adv. 4 em silêncio 5 em segredo; clandestinamente.</p></section></article>\n<article id=\"entry-dgp-36669\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιωπηλός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 519 na letra σ · nº geral 36669</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 silencioso; discreto; taciturno ♦ τὸ σιωπηλόν 2 taciturnidade. 〈σιωπάω〉</p></section></article>\n<article id=\"entry-dgp-36670\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σιωπητέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 520 na letra σ · nº geral 36670</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de σιωπάω.</p></section></article>\n<article id=\"entry-dgp-36671\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 521 na letra σ · nº geral 36671</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) 1 coxear 2 cambalear; estar pouco firme; vacilar; hesitar 3 Métr. ser desigual; ὁ σκά­ζων ou χωλίαμβος coxiambo, trímetro jâmbico que substituía por uma sílaba longa a última breve.</p></section></article>\n<article id=\"entry-dgp-36672\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σκαιαί, ῶν (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 522 na letra σ · nº geral 36672</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. σκαιός.</p></section></article>\n<article id=\"entry-dgp-36673\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαιός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 523 na letra σ · nº geral 36673</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 situado à esquerda; esquerdo (op. a δεξιός); χειρὶ σκαιῇ ou σκαιῇ à mão esquerda, da mão esquerda ou com a mão esquerda 2 ocidental: Σκαιαὶ πύλαι hom. ou Σκαιαί hom. as portas Céias na parte ocidental de Tróia 3 de mau presságio (pássaros que se mostravam à esquerda) 4 funesto; nocivo; sinistro 5 parcial 6 ignorante; grosseiro 7 oblíquo; enviesado.</p></section></article>\n<article id=\"entry-dgp-36674\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαιοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 524 na letra σ · nº geral 36674</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σκαιότης.</p></section></article>\n<article id=\"entry-dgp-36675\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαιότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 525 na letra σ · nº geral 36675</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falta de jeito; inabilidade; imperícia 2 grosseria 3 insensibilidade. 〈σκαιός〉</p></section></article>\n<article id=\"entry-dgp-36676\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαίρω</h1><div class=\"entry-meta\"><span>DGP · ordem 526 na letra σ · nº geral 36676</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) 1 pular; saltar 2 agitar-se.</p></section></article>\n<article id=\"entry-dgp-36677\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαιῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 527 na letra σ · nº geral 36677</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. inabilmente; desajeitadamente.</p></section></article>\n<article id=\"entry-dgp-36678\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαλεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 528 na letra σ · nº geral 36678</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que lavra ou monda a terra; carpidor; capinador. 〈σκάλλω〉</p></section></article>\n<article id=\"entry-dgp-36679\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 529 na letra σ · nº geral 36679</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escavar; cavoucar 2 atiçar (fogo): σκ. ἄνθρακας ar., σκ. πῦρ plut. atiçar o fogo ou a brasa, i.e., provocar alguém. 〈σκαλεύς〉</p></section></article>\n<article id=\"entry-dgp-36680\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαληνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 530 na letra σ · nº geral 36680</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">desigualdade; dessemelhança; irregularidade. 〈σκαληνός〉</p></section></article>\n<article id=\"entry-dgp-36681\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαληνός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 531 na letra σ · nº geral 36681</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desigual; irregular 2 coxo 3 tortuoso; oblíquo 4 ímpar (número) 5 Geom. escaleno (triângulo). 〈σκολιός〉</p></section></article>\n<article id=\"entry-dgp-36682\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαληνόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 532 na letra σ · nº geral 36682</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tornar-se oblíquo. 〈σκαληνός〉</p></section></article>\n<article id=\"entry-dgp-36683\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 533 na letra σ · nº geral 36683</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cavoucar; sachar; mondar 2 vasculhar; esquadrinhar; sondar.</p></section></article>\n<article id=\"entry-dgp-36684\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαλμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 534 na letra σ · nº geral 36684</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cavilha que prende o remo na amurada do navio 2 σ. θρανίτης banco superior de remadores. 〈σκάλλω〉</p></section></article>\n<article id=\"entry-dgp-36685\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκάλοψ, οπος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 535 na letra σ · nº geral 36685</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">toupeira. 〈σκάλλω〉</p></section></article>\n<article id=\"entry-dgp-36686\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σκαμάνδριος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 536 na letra σ · nº geral 36686</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do Escamandro ♦ ὁ Σκαμάν­δριος 2 Escamândrio, filho de Heitor. 〈Σκάμανδρος〉</p></section></article>\n<article id=\"entry-dgp-36687\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σκάμανδρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 537 na letra σ · nº geral 36687</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Escamandro, n. de rio da Trácia e do deus desse rio, e n. de h.</p></section></article>\n<article id=\"entry-dgp-36688\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκανδαλίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 538 na letra σ · nº geral 36688</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 causar escândalo; escandalizar ♦ pas. 2 ser escandalizado; ser ofendido.</p></section></article>\n<article id=\"entry-dgp-36689\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκάνδαλον, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 539 na letra σ · nº geral 36689</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(τό) 1 bíbl. armadilha no caminho dos inimigos; obstáculo para fazer cair 2 escândalo; ofensa.</p></section></article>\n<article id=\"entry-dgp-36690\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαπανεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 540 na letra σ · nº geral 36690</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σκαφεύς.</p></section></article>\n<article id=\"entry-dgp-36691\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαπάνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 541 na letra σ · nº geral 36691</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enxadão; alvião; pá 2 ação de escavar. 〈σκάπτω〉</p></section></article>\n<article id=\"entry-dgp-36692\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκᾶπτον</h1><div class=\"entry-meta\"><span>DGP · ordem 542 na letra σ · nº geral 36692</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = σκῆπτρον.</p></section></article>\n<article id=\"entry-dgp-36693\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαπτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 543 na letra σ · nº geral 36693</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cavado; escavado. 〈σκάπτω〉</p></section></article>\n<article id=\"entry-dgp-36694\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκᾶπτρον</h1><div class=\"entry-meta\"><span>DGP · ordem 544 na letra σ · nº geral 36694</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = σκῆπτρον.</p></section></article>\n<article id=\"entry-dgp-36695\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκάπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 545 na letra σ · nº geral 36695</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. σκάψω, aor. ἔσκαψα, perf. desus.; pas. aor.2 ἐσκάφην, perf. ἔσκαμμαι) 1 cavar 2 cavoucar; mondar ♦ pas. 3 ser escavado: τὰ ἐσκαμμένα vala escavada, limite para salto no pentatlo, prov. ὑπὲρ τὰ ἐσκαμμένα ἅλλεσθαι plat. saltar por cima do limite, ultrapassar os limites.</p></section></article>\n<article id=\"entry-dgp-36696\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαρδαμυκτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 546 na letra σ · nº geral 36696</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σκαρδαμύσσω.</p></section></article>\n<article id=\"entry-dgp-36697\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαρδαμύσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 547 na letra σ · nº geral 36697</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">piscar o olho; pestanejar. 〈σκαίρω, μύω〉</p></section></article>\n<article id=\"entry-dgp-36698\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκατός</h1><div class=\"entry-meta\"><span>DGP · ordem 548 na letra σ · nº geral 36698</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de σκώρ.</p></section></article>\n<article id=\"entry-dgp-36699\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκατοφάγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 549 na letra σ · nº geral 36699</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que come excrementos. 〈σκώρ, φαγεῖν〉</p></section></article>\n<article id=\"entry-dgp-36700\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκαφεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 550 na letra σ · nº geral 36700</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pá de cavar; enxada. 〈σκάφη〉</p></section></article>\n";
